head.script:
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 CheckCombobox 에 ▼ 버튼을 클릭한다.
    //1. In the browser, click the ▼ button on the CheckCombobox.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_button').click()");
    //Verify step 1. 리스트가 전체체크되어 있다.(2016년 07월 08일 엔진에서는 리스트의 체크박스가 다 해제되어 있었다.)
    //1. The list is fully checked. (On the 07/08/2010 engine, the checkboxes in the list were all cleared.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_0_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_1_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_2_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_3_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_4_checkbox').checked", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    checkcombobox1.checkAll(true);
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 27-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
